const questions = [
  { type: "CONCEPT", question: "What does a production possibility curve (PPC) show?", options: ["The maximum profit a firm can earn", "The maximum combinations of two goods that can be produced with available resources and technology", "The total demand for two goods", "The combinations consumers prefer"], answer: 1, explanation: "A PPC is a boundary showing the maximum attainable combinations of two goods, given fixed resources and technology.", why: ["This describes profit, not the economy's production limit.", "Correct. It captures scarcity, resources, technology, and the tradeoff between two outputs.", "Demand is represented by a demand curve, not a PPC.", "Preferences help determine choice, but do not define the production frontier."] },
  { type: "GRAPH", question: "In the graph, a point on the PPC represents a combination that is...", visual: graph.basic, options: ["Unattainable with current resources", "Inefficient because resources are idle", "Productively efficient and attainable", "Always the socially preferred choice"], answer: 2, explanation: "Every point on the frontier is attainable and uses available resources efficiently. The PPC does not tell us which efficient point society prefers.", why: ["Points beyond the curve are unattainable, not points on it.", "Points inside the curve indicate inefficiency; points on it are efficient.", "Correct. The frontier marks maximum attainable output combinations.", "Efficiency does not automatically determine social preference or equity."] },
  { type: "CONCEPT", question: "A point inside a country's PPC most directly indicates...", options: ["Economic growth", "Underused resources or productive inefficiency", "An impossible production plan", "Full productive efficiency"], answer: 1, explanation: "An interior point is attainable, but the economy could produce more of at least one good without producing less of the other.", why: ["Growth shifts the PPC outward; it is not represented by an interior point.", "Correct. Idle labor, unemployment, or poor organization can place production inside the curve.", "Points outside the curve are currently unattainable.", "Full efficiency is represented by points on the PPC."] },
  { type: "GRAPH", question: "Point C lies outside the PPC shown. What is the best interpretation?", visual: graph.points, options: ["It is efficient and attainable today", "It is inefficient but attainable today", "It represents the economy's current equilibrium", "It is unattainable with current resources and technology"], answer: 3, explanation: "Point C is outside the frontier, so current resources and technology cannot produce that combination. It may become attainable after growth or technological progress.", why: ["A point on the curve, such as A or B, is efficient and attainable.", "Interior points are attainable but inefficient; C is beyond the frontier.", "The graph gives no information about equilibrium or market clearing.", "Correct. Outside the PPC means unattainable under current conditions."] },
  { type: "CONCEPT", question: "A bowed-out PPC usually reflects...", visual: graph.basic, options: ["Constant opportunity cost", "Increasing opportunity cost", "Zero opportunity cost", "A lack of scarcity"], answer: 1, explanation: "As more of one good is produced, increasingly less-suitable resources are pulled away from the other good. Its opportunity cost rises.", why: ["A straight-line PPC usually represents constant opportunity cost.", "Correct. The bowed-out shape reflects increasing opportunity cost.", "Scarcity means opportunity cost is generally not zero.", "The PPC exists precisely because resources are scarce."] },
  { type: "CALCULATION", question: "An economy moves from producing (0 computers, 20 tons of food) to (5 computers, 18 tons of food). What is the opportunity cost of the 5 computers?", options: ["2 tons of food", "5 tons of food", "18 tons of food", "23 tons of food"], answer: 0, explanation: "Opportunity cost is what is given up. Food falls from 20 to 18, so the cost of producing 5 computers is 2 tons of food.", why: ["Correct. The reduction in food is 20 - 18 = 2 tons.", "The 5 is the quantity of computers gained, not the food cost.", "18 is the final food output, not what was sacrificed.", "23 adds outputs; opportunity cost measures the forgone alternative."] },
  { type: "CONCEPT", question: "If a PPC is a straight line, the opportunity cost of one more unit of either good is...", visual: graph.line, options: ["Increasing", "Decreasing", "Constant", "Impossible to calculate"], answer: 2, explanation: "A straight-line PPC has a constant slope, so each additional unit of one good requires the same sacrifice of the other good.", why: ["Increasing opportunity cost produces a bowed-out curve.", "Decreasing opportunity cost would produce a bowed-in curve.", "Correct. A constant slope means a constant opportunity cost.", "The slope of the line allows the cost to be calculated."] },
  { type: "CONCEPT", question: "Which event would most likely shift a nation's entire PPC outward?", visual: graph.shifts, options: ["A temporary rise in unemployment", "A fall in worker productivity", "A discovery that improves technology for both goods", "Moving from an interior point to the curve"], answer: 2, explanation: "Technology that raises the productive capacity for both goods expands the entire set of attainable combinations, shifting the PPC outward.", why: ["Unemployment moves production toward the frontier; it does not expand the frontier.", "Lower productivity reduces capacity and may shift the PPC inward.", "Correct. Broad technological progress increases productive capacity.", "This is a movement to a point on the existing PPC, not a shift."] },
  { type: "CONCEPT", question: "A PPC shifts inward when...", options: ["The labor force becomes more skilled", "A natural disaster destroys factories and farmland", "Workers return from unemployment", "A new resource is discovered"], answer: 1, explanation: "An inward shift means the economy can produce less than before. Destruction of productive resources reduces capacity.", why: ["Skills generally expand productive capacity and shift the PPC outward.", "Correct. Destroyed resources lower the maximum possible output.", "Returning workers to production moves the economy toward the existing curve.", "A new resource expands the frontier rather than contracting it."] },
  { type: "CONCEPT", question: "Which statement best describes scarcity and the PPC?", options: ["Scarcity means every want can be satisfied", "Scarcity creates the need to choose among alternative uses of limited resources", "Scarcity exists only in poor countries", "Scarcity eliminates opportunity cost"], answer: 1, explanation: "Limited resources and unlimited wants force choices. The PPC makes those choices and their opportunity costs visible.", why: ["Scarcity means resources are insufficient for every want.", "Correct. Limited resources require choices between alternatives.", "Scarcity is a universal economic condition.", "Scarcity creates opportunity cost rather than eliminating it."] },
  { type: "CALCULATION", question: "A straight-line PPC has endpoints of 40 units of wheat and 20 units of cloth. What is the opportunity cost of 1 unit of cloth?", options: ["0.5 units of wheat", "2 units of wheat", "20 units of wheat", "40 units of wheat"], answer: 1, explanation: "Moving from all wheat to all cloth gives up 40 wheat for 20 cloth. Cost per cloth = 40 / 20 = 2 wheat.", why: ["0.5 is the reverse ratio: cloth per wheat, not wheat per cloth.", "Correct. 40 wheat / 20 cloth = 2 wheat per cloth.", "20 is the total cloth endpoint, not the cost of one cloth.", "40 is the total wheat forgone for all 20 cloth, not for one unit."] },
  { type: "CONCEPT", question: "Economic growth is represented on a PPC diagram by...", options: ["A movement from a point on the curve to an interior point", "A shift of the PPC outward", "A shift of the PPC inward", "A movement along the same curve only"], answer: 1, explanation: "Growth increases an economy's productive capacity, so the whole frontier shifts outward.", why: ["Moving inward reflects lower production or unused resources.", "Correct. An outward shift means more can be produced at every tradeoff.", "An inward shift indicates a loss of capacity.", "A movement along the same curve changes the mix, not total capacity."] },
  { type: "CALCULATION", question: "A PPC follows the equation 2X + Y = 20. If X = 6, what is the maximum Y?", options: ["6", "8", "12", "20"], answer: 1, explanation: "Substitute X = 6: 2(6) + Y = 20, so 12 + Y = 20 and Y = 8.", why: ["6 is the value of X, not the solved value of Y.", "Correct. Y = 20 - 12 = 8.", "12 is 2X, the amount of the constraint used by X.", "20 is the maximum Y only when X = 0."] },
  { type: "CONCEPT", question: "The slope of a PPC measures...", options: ["Total economic profit", "The opportunity cost of one good in terms of the other", "The level of consumer satisfaction", "The amount of money in circulation"], answer: 1, explanation: "The slope compares the change in one output with the change in the other output. In absolute value, it measures opportunity cost.", why: ["Profit requires revenue and cost information, not just output combinations.", "Correct. The PPC slope is the tradeoff between the two goods.", "Satisfaction is not measured by the production frontier.", "Money supply is a macroeconomic policy variable."] },
  { type: "CALCULATION", question: "At point A, an economy makes 10 cars and 30 buses. At point B, it makes 12 cars and 24 buses. What is the opportunity cost per additional car?", options: ["2 buses", "3 buses", "6 buses", "12 buses"], answer: 1, explanation: "The economy gains 2 cars and gives up 6 buses. The cost per car is 6 / 2 = 3 buses.", why: ["2 is the number of cars gained, not the buses sacrificed per car.", "Correct. 6 buses / 2 cars = 3 buses per car.", "6 is the total number of buses given up for both cars.", "12 is the final number of cars, not the opportunity cost."] },
  { type: "CONCEPT", question: "Why does the PPC illustrate a tradeoff?", options: ["Resources can produce unlimited amounts of both goods", "Resources used to produce one good cannot simultaneously produce as much of the other", "Prices are always fixed", "Consumers always buy both goods equally"], answer: 1, explanation: "With limited resources, producing more of one good generally means redirecting resources away from the other.", why: ["Unlimited resources would remove the tradeoff.", "Correct. Resource constraints force the economy to give up some alternative output.", "Prices are not required for a PPC tradeoff to exist.", "Consumer buying patterns do not define the production constraint."] },
  { type: "CONCEPT", question: "Which change would move an economy along its PPC rather than shift the PPC?", options: ["Choosing to produce more medical equipment and fewer cars", "An invention that improves both industries", "A larger labor force", "The destruction of capital"], answer: 0, explanation: "Changing the chosen mix of outputs, while resources and technology stay fixed, moves the economy to another point on the same frontier.", why: ["Correct. A different output mix is a movement along the same PPC.", "Broad innovation shifts the PPC outward.", "More labor expands productive capacity.", "Destroyed capital shifts the PPC inward."] },
  { type: "CALCULATION", question: "A country can produce either 100 units of food or 50 units of clothing, with a linear PPC. What is the opportunity cost of 25 units of clothing?", options: ["12.5 units of food", "25 units of food", "50 units of food", "100 units of food"], answer: 2, explanation: "The tradeoff is 100 food for 50 clothing, or 2 food per clothing. Therefore 25 clothing costs 25 x 2 = 50 food.", why: ["12.5 uses the reversed ratio.", "25 is the clothing quantity, not the forgone food.", "Correct. 25 clothing x 2 food per clothing = 50 food.", "100 food is the cost of producing all 50 clothing."] },
  { type: "CONCEPT", question: "Which assumption is commonly made when using a basic two-good PPC model?", options: ["Resources and technology are held constant", "All resources are unlimited", "The economy produces no goods", "Opportunity cost does not exist"], answer: 0, explanation: "Holding resources and technology constant lets the model focus on the tradeoff between the two outputs.", why: ["Correct. This ceteris paribus assumption defines the current frontier.", "Unlimited resources would make the frontier and scarcity irrelevant.", "The model describes possible production, not zero production.", "Opportunity cost is the central idea illustrated by a PPC."] },
  { type: "CONCEPT", question: "If resources are specialized, shifting resources between two goods will generally cause...", options: ["A constant opportunity cost", "An increasing opportunity cost", "No opportunity cost", "An inward shift in every case"], answer: 1, explanation: "Specialized resources are better suited to some tasks than others. As production expands, less-suitable resources must be reassigned, raising the opportunity cost.", why: ["Constant cost requires a straight-line PPC and interchangeable resources.", "Correct. Specialization helps explain the bowed-out PPC.", "Every choice among scarce resources has an opportunity cost.", "Reallocating resources changes the mix; it does not automatically shrink capacity."] },
  { type: "CALCULATION", question: "A PPC table shows: 0 bikes/60 helmets, 10 bikes/54 helmets, 20 bikes/44 helmets. What is the cost of the second 10 bikes?", options: ["6 helmets", "10 helmets", "12 helmets", "16 helmets"], answer: 1, explanation: "For the second 10 bikes, compare 10 bikes/54 helmets with 20 bikes/44 helmets. Helmets fall by 10, so the cost is 10 helmets.", why: ["6 helmets is the cost of the first 10 bikes, from 60 down to 54.", "Correct. The second 10 bikes cost 54 - 44 = 10 helmets.", "12 is the total helmet loss from 0 to 20 bikes, not the second increment.", "16 does not match either relevant change in the table."] },
  { type: "CONCEPT", question: "If an economy is operating at a point on its PPC, which statement must be true?", options: ["The economy is using resources productively efficiently", "Everyone receives equal income", "The output mix is socially fair", "The economy has no unemployment of any type"], answer: 0, explanation: "A point on the frontier indicates productive efficiency under the model. It does not establish fairness, equality, or the absence of frictional unemployment.", why: ["Correct. The economy cannot increase one output without reducing the other at that point.", "The PPC says nothing about income distribution.", "Productive efficiency is different from social fairness.", "The simple PPC does not identify every kind of unemployment."] },
  { type: "GRAPH", question: "The dashed curve is PPC1 and the solid curve is PPC2. What could cause the outward shift to PPC2?", visual: graph.shifts, options: ["A fall in productivity", "A war that destroys factories", "Investment in new productive capital", "A move from an interior point to PPC1"], answer: 2, explanation: "Investment adds capital and can increase the economy's maximum output, shifting the frontier outward.", why: ["Lower productivity reduces the frontier.", "Destroyed factories reduce productive capacity.", "Correct. New capital can expand productive capacity.", "A movement to PPC1 changes actual production but does not shift the frontier."] },
  { type: "CALCULATION", question: "If the PPC slope is -3, what is the opportunity cost of producing 4 additional units of Good X?", options: ["1 unit of Good Y", "3 units of Good Y", "7 units of Good Y", "12 units of Good Y"], answer: 3, explanation: "The absolute slope is 3, so each additional X costs 3 units of Y. Four X cost 4 x 3 = 12 Y.", why: ["1 is not the slope's tradeoff.", "3 is the cost of one X, not four X.", "7 has no basis in the given slope.", "Correct. 4 X x 3 Y per X = 12 Y."] },
  { type: "CONCEPT", question: "A country produces at an interior point during a recession. Which policy outcome would move production closer to the PPC without shifting it?", options: ["Using fiscal or monetary policy to support aggregate demand and employment", "Inventing a new production technology", "Discovering a large oil reserve", "Destroying obsolete factories"], answer: 0, explanation: "When capacity exists but resources are idle, stronger demand and employment can move actual output toward the existing frontier. Technology and resources shift the frontier.", why: ["Correct. It can activate idle resources and raise actual output toward capacity.", "New technology shifts the PPC outward.", "New resources shift the PPC outward.", "Destruction reduces the frontier's capacity."] },
  { type: "CALCULATION", question: "A country moves from 30 food and 5 machines to 24 food and 7 machines. What is the opportunity cost of each additional machine?", options: ["2 units of food", "3 units of food", "6 units of food", "12 units of food"], answer: 1, explanation: "The country gains 2 machines and gives up 6 food. The cost per machine is 6 / 2 = 3 food.", why: ["2 is the number of machines gained, not food per machine.", "Correct. 6 food / 2 machines = 3 food per machine.", "6 is the total food sacrificed for both machines.", "12 doubles the actual total sacrifice and is not supported by the data."] },
  { type: "GRAPH", question: "Which labeled location would be productively inefficient in the graph?", visual: graph.points, options: ["A, because it is inside the PPC", "B, because it is on the PPC", "C, because it is outside the PPC", "None of them; all locations have the same meaning"], answer: 0, explanation: "Point A is inside the frontier, so the economy could increase at least one output without reducing the other. B is efficient; C is unattainable.", why: ["Correct. Interior point A indicates unused resources or inefficiency.", "A point on the PPC is productively efficient.", "An outside point is unattainable, not inefficient production.", "The locations have different economic meanings."] },
  { type: "CALCULATION", question: "A PPC allows 80 units of Y when X = 0 and 20 units of X when Y = 0. If it is linear, what is the opportunity cost of 1 unit of X?", options: ["0.25 units of Y", "4 units of Y", "20 units of Y", "80 units of Y"], answer: 1, explanation: "The economy gives up 80 Y to gain 20 X. The cost per X is 80 / 20 = 4 Y.", why: ["0.25 is the reverse ratio: X per Y.", "Correct. 80 Y / 20 X = 4 Y per X.", "20 is the maximum X, not the cost of one X.", "80 is the total Y sacrificed for all 20 X."] },
  { type: "CONCEPT", question: "Which statement distinguishes productive efficiency from allocative efficiency?", options: ["Productive efficiency means being on the PPC; allocative efficiency means choosing the point that best matches society's preferences", "They are exactly the same concept", "Productive efficiency is inside the PPC; allocative efficiency is outside it", "Allocative efficiency concerns only a firm's accounting profit"], answer: 0, explanation: "Productive efficiency concerns whether resources are fully and effectively used. Allocative efficiency concerns whether the chosen mix reflects society's marginal benefits and costs.", why: ["Correct. The PPC identifies productive efficiency, while preferences help identify the allocatively best point.", "They are related but not identical.", "The locations are reversed: an interior point is productively inefficient, and an outside point is unattainable.", "Allocative efficiency is a broader social choice, not just accounting profit."] },
  { type: "CONCEPT", question: "If technology improves only the production of Good X, the PPC will most likely...", options: ["Shift outward equally along both axes", "Pivot outward on the X-axis side", "Shift inward equally along both axes", "Disappear because opportunity cost is zero"], answer: 1, explanation: "A technology improvement specific to X raises the maximum possible X and changes tradeoffs involving X, so the frontier pivots outward toward the X intercept.", why: ["Equal improvement for both goods would be needed for an equal outward shift.", "Correct. Only X's productive capacity improves, producing an asymmetric shift.", "The improvement does not reduce capacity.", "Opportunity cost remains because resources remain scarce."] },
];

const advancedQuestions = [
  // Consumer theory
  { type: "CONSUMER THEORY", question: "For an interior utility maximum, which condition must hold?", options: ["MUx = MUy regardless of prices", "MUx / MUy = Px / Py", "Px / Py = income", "MRS = 0"], answer: 1, explanation: "At an interior tangency, the consumer's willingness to trade X for Y equals the market tradeoff, so MRS = MUx/MUy = Px/Py.", why: ["Marginal utilities need not be equal because prices can differ.", "Correct. Equalizing marginal utility per dollar gives MUx/Px = MUy/Py.", "Relative prices, not the income level, determine the tangency condition.", "An MRS of zero would not generally describe an interior optimum."] },
  { type: "CALCULATION", question: "A consumer has U = x^0.4 y^0.6, income 100, Px = 5, and Py = 2. What is the Marshallian demand for x?", options: ["4 units", "8 units", "20 units", "40 units"], answer: 1, explanation: "For a Cobb-Douglas utility function, the consumer spends the exponent share on each good. Spending on x is 0.4(100) = 40, so x = 40/5 = 8.", why: ["4 ignores the 40 percent expenditure share calculation.", "Correct. x = 0.4I/Px = 0.4(100)/5 = 8.", "20 is income divided by price without applying the utility share.", "40 is expenditure on x, not the quantity of x."] },
  { type: "CONSUMER THEORY", question: "If MUx = 12, MUy = 6, Px = 3, and Py = 1, what should an interior consumer do at the current bundle?", options: ["Buy more x because MUx/Px is larger", "Buy more y because MUy/Py is larger", "Keep the bundle because MRS equals the price ratio", "Buy less of both goods"], answer: 1, explanation: "MUx/Px = 4 while MUy/Py = 6. Utility per dollar is higher for y, so the consumer should shift spending toward y.", why: ["x gives 4 utility per dollar, less than y's 6.", "Correct. The consumer should favor y until marginal utility per dollar is equalized.", "MRS = 12/6 = 2, while Px/Py = 3, so they are not equal.", "The comparison indicates reallocation, not that both goods should fall."] },
  { type: "CONSUMER THEORY", question: "A Giffen good is necessarily...", options: ["A normal good with a positive income effect", "An inferior good whose negative income effect exceeds its substitution effect", "A luxury good with unitary elasticity", "A good with no substitution effect"], answer: 1, explanation: "For a Giffen good, a price increase raises quantity demanded because the negative income effect dominates the substitution effect. Inferiority is necessary, but not every inferior good is Giffen.", why: ["A normal good has a positive income effect, making Giffen behavior impossible.", "Correct. The sufficiently strong negative income effect reverses the usual law of demand.", "Luxury status is unrelated to the Giffen condition.", "There is still a substitution effect; it is simply dominated."] },
  { type: "CONSUMER THEORY", question: "Under the Slutsky decomposition, a price increase for a normal good has...", options: ["A positive substitution effect and positive income effect", "A negative substitution effect and negative income effect", "A zero substitution effect and negative income effect", "A positive substitution effect and zero income effect"], answer: 1, explanation: "A price increase makes the good relatively more expensive, producing a negative substitution effect. For a normal good, the loss of real income also reduces demand, giving a negative income effect.", why: ["The substitution effect moves consumption away from the relatively more expensive good.", "Correct. Both effects reduce demand for a normal good after a price increase.", "The substitution effect is not zero when relative prices change.", "The income effect for a normal good is not zero."] },
  { type: "CONSUMER THEORY", question: "If a consumer strictly prefers bundle A to bundle B, and B is revealed preferred to A, which principle is violated?", options: ["The law of demand", "Weak axiom of revealed preference", "The envelope theorem", "The law of diminishing returns"], answer: 1, explanation: "WARP rules out directly revealed preference cycles: if B was chosen when A was affordable, choosing A when B is affordable contradicts strict preference.", why: ["The law of demand concerns price and quantity, not revealed preference consistency.", "Correct. The choices create a direct revealed-preference reversal.", "The envelope theorem concerns value functions and derivatives.", "Diminishing returns concerns production, not consumer choice."] },
  { type: "CALCULATION", question: "For a CES utility function with parameter rho = 0.5, what is the elasticity of substitution sigma = 1/(1-rho)?", options: ["0.5", "1", "2", "4"], answer: 2, explanation: "Substitute rho = 0.5: sigma = 1/(1 - 0.5) = 1/0.5 = 2.", why: ["0.5 is the CES parameter, not the resulting elasticity.", "1 would be the Cobb-Douglas case, not rho = 0.5.", "Correct. sigma = 2.", "4 uses an incorrect denominator or reciprocal operation."] },
  { type: "CONSUMER THEORY", question: "A corner solution for good x is most likely when...", options: ["The indifference curve is tangent to the budget line at an interior point", "The consumer's MRS for x exceeds the price ratio everywhere over the feasible set", "The consumer has strictly convex preferences", "Income is positive"], answer: 1, explanation: "If the consumer always values x relatively more than the market does, the optimum occurs at the maximum feasible amount of x, a corner.", why: ["Tangency identifies an interior solution, not a corner.", "Correct. The consumer wants to substitute toward x at every feasible bundle.", "Strict convexity often supports unique interior optima, though constraints can still matter.", "Positive income alone does not identify the location of the optimum."] },
  { type: "CALCULATION", question: "Demand is Q = 100 - 2P. What is consumer surplus when P = 20?", options: ["300", "600", "900", "2,000"], answer: 2, explanation: "At P = 20, Q = 60. The choke price is 50, so consumer surplus is 0.5(50 - 20)(60) = 900.", why: ["300 omits the full triangle base or height.", "600 is not the area of the demand triangle for Q = 60 and height 30.", "Correct. Consumer surplus is 0.5 x 30 x 60 = 900.", "2,000 is not consistent with the demand intercept and equilibrium quantity."] },
  { type: "CONSUMER THEORY", question: "If all prices and income double, a homothetic consumer's demand bundle will generally...", options: ["Be unchanged because the real budget set is unchanged", "Double in every dimension", "Be cut in half", "Become infeasible"], answer: 0, explanation: "Doubling all prices and nominal income leaves the real budget set and relative prices unchanged. Demand is therefore unchanged, not doubled.", why: ["Correct. The budget equation divided by the common factor is identical.", "Quantities do not double because real purchasing power has not changed.", "There is no reason for quantities to halve.", "The original bundle remains exactly affordable in real terms."] },
  // Production, costs, and supply
  { type: "PRODUCTION", question: "For an interior cost-minimizing input choice, the firm satisfies...", options: ["MPL = MPK", "MPL / MPK = w / r", "w / r = output", "MPL / w = MPK / r is never relevant"], answer: 1, explanation: "The firm equalizes the marginal product per dollar: MPL/w = MPK/r, which rearranges to MPL/MPK = w/r.", why: ["Input marginal products need not be equal when input prices differ.", "Correct. The technical tradeoff equals the input-price tradeoff.", "Output does not determine the first-order input condition.", "The marginal-product-per-dollar condition is precisely the relevant rule."] },
  { type: "CALCULATION", question: "A production function is Q = K^0.4 L^0.6. What type of returns to scale does it exhibit?", options: ["Increasing returns because 0.4 + 0.6 > 1", "Constant returns because 0.4 + 0.6 = 1", "Decreasing returns because both exponents are below 1", "Returns cannot be inferred from exponents"], answer: 1, explanation: "For a Cobb-Douglas production function, the sum of exponents determines returns to scale. Here 0.4 + 0.6 = 1, so returns are constant.", why: ["The sum is not greater than 1.", "Correct. Scaling both inputs by t scales output by t.", "Individual diminishing marginal products do not imply decreasing returns to scale.", "The exponents directly identify returns to scale in this form."] },
  { type: "PRODUCTION", question: "A necessary condition for an interior profit maximum is...", options: ["P = average total cost", "MR = MC and the second-order condition is satisfied", "MC = 0", "Revenue is maximized rather than profit"], answer: 1, explanation: "Profit is maximized where marginal revenue equals marginal cost, provided the profit function is locally concave or the relevant second-order condition holds.", why: ["P = ATC describes zero economic profit in perfect competition, not the general first-order condition.", "Correct. MR = MC is necessary, and the second-order condition distinguishes a maximum.", "MC need not be zero.", "Revenue maximization ignores production costs and generally differs from profit maximization."] },
  { type: "COSTS", question: "In the short run, an increase in fixed cost will...", options: ["Shift MC upward", "Increase AVC at every output", "Raise ATC but leave MC and AVC unchanged", "Reduce the shutdown price"], answer: 2, explanation: "Fixed cost does not vary with output, so it affects total and average total cost but not marginal or average variable cost.", why: ["Marginal cost measures the change in variable cost from another unit.", "AVC excludes fixed cost by definition.", "Correct. ATC rises while MC and AVC are unchanged.", "The shutdown condition depends on AVC, so it is unaffected."] },
  { type: "CALCULATION", question: "A competitive firm faces P = 18 and has AVC = 20 at its profit-maximizing output. What should it do in the short run?", options: ["Produce because price exceeds ATC", "Shut down because price is below AVC", "Produce where P = ATC", "Raise its price above 18"], answer: 1, explanation: "The firm shuts down when price is below minimum AVC because operating would not cover variable costs. Fixed costs are then unavoidable.", why: ["The stated AVC is already above price, so producing loses more than shutting down.", "Correct. P < AVC means the shutdown rule is met.", "P = ATC is a zero-profit condition, not the shutdown rule.", "A price-taking firm cannot choose its market price."] },
  { type: "COSTS", question: "In long-run competitive equilibrium with free entry and identical firms, economic profit is...", options: ["Positive because firms set price above MC", "Zero because P is driven to minimum LRAC", "Negative because firms produce at minimum AVC", "Always equal to accounting profit"], answer: 1, explanation: "Entry expands industry supply when profits are positive until price equals minimum LRAC, leaving zero economic profit.", why: ["Perfectly competitive firms take price and P = MC; long-run entry removes positive economic profit.", "Correct. Free entry and exit drive P to minimum LRAC.", "Minimum AVC is a short-run shutdown concept.", "Economic profit subtracts opportunity costs, unlike accounting profit."] },
  { type: "COSTS", question: "A firm experiences economies of scale over an output range when...", options: ["LRAC rises as output rises", "LRAC falls as output rises", "MC is always zero", "Fixed cost is zero"], answer: 1, explanation: "Economies of scale mean average cost decreases as all inputs and output expand in the long run.", why: ["Rising LRAC is diseconomies of scale.", "Correct. Falling LRAC indicates spreading or coordinating inputs more efficiently.", "Marginal cost need not be zero.", "Economies can occur with positive fixed costs."] },
  { type: "CALCULATION", question: "A firm's cost function is C(q,w) = w^2 q + 10. By Shephard's lemma, its conditional demand for labor is...", options: ["2wq", "w^2", "2wq + 10", "q"], answer: 0, explanation: "Shephard's lemma gives labor demand as the derivative of the cost function with respect to the wage: dC/dw = 2wq.", why: ["Correct. Differentiate w^2q with respect to w.", "This omits the output term.", "The fixed cost does not enter the derivative, and the derivative is not C itself.", "q is not the derivative with respect to the wage."] },
  { type: "PRODUCTION", question: "Hotelling's lemma implies that the derivative of a firm's profit function with respect to output price equals...", options: ["The firm's input demand", "The firm's supply of output", "The firm's fixed cost", "The consumer's demand"], answer: 1, explanation: "Under the envelope theorem, differentiating maximized profit with respect to the output price returns the profit-maximizing quantity supplied.", why: ["Input demand is obtained by differentiating cost or profit with respect to input prices with a sign adjustment.", "Correct. d pi(p,w)/dp = q(p,w).", "Fixed cost is not the derivative of profit with respect to output price.", "Consumer demand is a separate market side."] },
  // Perfect competition and market intervention
  { type: "PERFECT COMPETITION", question: "For a competitive firm with an upward-sloping MC curve, the short-run supply curve is...", options: ["The entire ATC curve", "The MC curve above the minimum of AVC", "The demand curve facing the industry", "The portion of MC below minimum AVC"], answer: 1, explanation: "Above shutdown, each price maps to the output where P = MC. Below minimum AVC, the firm produces zero, so that portion is not supply.", why: ["ATC does not determine the firm's output response to price.", "Correct. MC above min AVC is the firm's short-run supply.", "A competitive firm faces a horizontal market price, not industry demand.", "Below minimum AVC the firm shuts down."] },
  { type: "CALCULATION", question: "Demand is P = 100 - Q and supply is P = 20 + Q. A per-unit tax of 20 is imposed on sellers. What is the buyer price after tax?", options: ["40", "60", "80", "90"], answer: 2, explanation: "With tax t, buyer price equals seller price plus 20. Equating 100 - Q = 20 + Q + 20 gives Q = 20, so the buyer price is 80.", why: ["40 is below the pre-tax equilibrium and does not satisfy demand at the taxed quantity.", "60 does not satisfy the taxed supply and demand equations.", "Correct. Q = 20, buyer price = 100 - 20 = 80, and seller price is 60.", "90 is above the demand price at the equilibrium quantity."] },
  { type: "WELFARE", question: "If demand is perfectly inelastic, a specific tax on a good is borne primarily by...", options: ["Consumers, because quantity demanded does not respond", "Producers, because supply is irrelevant", "The government, through lower tax revenue", "No one, because tax incidence disappears"], answer: 0, explanation: "With perfectly inelastic demand, consumers do not reduce quantity, so the buyer price rises by approximately the full tax.", why: ["Correct. The inelastic side of the market bears more of the tax burden.", "Producers may bear some burden depending on supply elasticity, but not necessarily all.", "Government collects revenue rather than bearing incidence.", "Tax incidence does not disappear; it depends on elasticities."] },
  { type: "WELFARE", question: "A binding price ceiling below equilibrium generally creates...", options: ["A surplus and upward pressure on price", "A shortage and non-price rationing", "No change because price ceilings are always irrelevant", "A larger quantity supplied than demanded"], answer: 1, explanation: "At the controlled price, quantity demanded exceeds quantity supplied. The resulting shortage may be allocated through queues, favoritism, or black markets.", why: ["A price floor above equilibrium creates a surplus; a ceiling creates a shortage.", "Correct. The lower legal price increases quantity demanded and reduces quantity supplied.", "A ceiling below equilibrium is binding and changes the market outcome.", "The shortage means supplied quantity is less than demanded quantity."] },
  { type: "MONOPOLY", question: "For demand P = 100 - 2Q and constant MC = 20, what are the monopoly quantity and price?", options: ["Q = 20, P = 60", "Q = 30, P = 40", "Q = 40, P = 20", "Q = 10, P = 80"], answer: 0, explanation: "TR = 100Q - 2Q^2, so MR = 100 - 4Q. Set MR = MC: 100 - 4Q = 20, yielding Q = 20 and P = 60.", why: ["Correct. MR = MC gives Q = 20, and demand gives P = 60.", "At Q = 30, MR is -20, not 20.", "Q = 40 gives price 20 and MR = -60.", "At Q = 10, MR = 60, so the firm could profitably expand."] },
  { type: "MONOPOLY", question: "If a monopolist faces demand elasticity of -2 at its optimum, the Lerner index (P - MC)/P equals...", options: ["0.25", "0.5", "2", "4"], answer: 1, explanation: "The monopoly pricing rule is (P - MC)/P = -1/e, using the absolute value of elasticity. With e = -2, the markup index is 1/2.", why: ["0.25 would correspond to an elasticity magnitude of 4.", "Correct. -1/(-2) = 0.5.", "2 is the elasticity magnitude, not the markup share.", "4 reverses the relationship incorrectly."] },
  { type: "MONOPOLY", question: "A third-degree price discriminator allocates output across separated markets by setting...", options: ["The same price in every market", "MR1 = MR2 = MC", "P1 = P2 = MC regardless of demand", "The highest possible price in every market"], answer: 1, explanation: "Profit maximization requires the marginal revenue from the last unit sold in each market to equal the common marginal cost.", why: ["Different elasticities generally lead to different prices.", "Correct. The firm equalizes marginal revenue across markets and with MC.", "Price need not equal MC under market power.", "A price that is too high can reduce profitable sales."] },
  { type: "MONOPOLY", question: "A two-part tariff can extract consumer surplus most completely when the firm...", options: ["Charges a low entry fee and a price above MC", "Charges an entry fee equal to surplus and a per-unit price equal to MC", "Charges only a tax on output", "Sets the per-unit price at the monopoly price and no fee"], answer: 1, explanation: "With identical consumers and verifiable participation, setting per-unit price at MC maximizes total surplus, then using the fixed fee to capture that surplus extracts it.", why: ["A price above MC creates avoidable deadweight loss and leaves less surplus to extract.", "Correct. The fee captures surplus while marginal pricing preserves efficient quantity.", "A tax is not the standard two-part tariff mechanism.", "Monopoly pricing leaves deadweight loss and may not extract all surplus."] },
  { type: "MONOPOLY", question: "For a natural monopoly with declining LRAC over the relevant demand range, marginal-cost pricing may...", options: ["Always generate positive profit", "Require a subsidy because P = MC can be below ATC", "Be impossible to calculate", "Create no output"], answer: 1, explanation: "When LRAC is declining, average cost exceeds marginal cost. Regulating price at MC can therefore create losses that require a subsidy.", why: ["P = MC can be below ATC, so profit need not be positive.", "Correct. The regulator may need to cover the firm's fixed costs.", "The rule is conceptually calculable even if implementation is difficult.", "The regulated quantity is generally positive if demand is positive."] },
  { type: "WELFARE", question: "Compared with perfect competition, an unregulated single-price monopoly usually produces...", options: ["More output at a lower price", "Less output at a higher price and creates deadweight loss", "The efficient output because MR = MC", "The same output because demand is unchanged"], answer: 1, explanation: "A monopoly restricts output until MR = MC, while efficiency requires P = MC. The resulting wedge creates mutually beneficial trades that do not occur.", why: ["The monopoly's output restriction raises rather than lowers price.", "Correct. Market power produces higher price, lower output, and deadweight loss.", "MR = MC maximizes profit, not total surplus.", "Unchanged demand does not imply unchanged quantity when market structure changes."] },
  // Oligopoly, strategic behavior, and auctions
  { type: "COURNOT", question: "In a symmetric Cournot duopoly with P = 120 - Q and zero marginal cost, each firm's equilibrium output is...", options: ["20", "30", "40", "60"], answer: 2, explanation: "Firm i's best response is qi = (120 - qj)/2. Symmetry gives q = (120 - q)/2, so 3q = 120 and q = 40.", why: ["20 is too low given the firm's best-response incentive.", "30 does not solve the symmetric best-response equation.", "Correct. Each firm produces 40, total output is 80, and price is 40.", "60 would be the monopoly output if a single firm faced the demand curve."] },
  { type: "OLIGOPOLY", question: "With homogeneous products, identical constant MC, and Bertrand competition, the Nash equilibrium price is...", options: ["The monopoly price", "The Cournot price", "Marginal cost", "The average total cost plus a markup"], answer: 2, explanation: "Each firm can undercut any price above MC and capture the market, so price is competed down to MC.", why: ["A monopoly price can be undercut profitably.", "Cournot assumes quantity competition and gives a different result.", "Correct. Bertrand price competition with identical products yields P = MC.", "A positive markup invites undercutting under the stated assumptions."] },
  { type: "CALCULATION", question: "In Stackelberg quantity competition with P = 100 - Q and zero cost, the follower chooses qF = (100 - qL)/2. What is the leader's optimal output?", options: ["25", "40", "50", "100"], answer: 2, explanation: "Substitute the follower response: P = (100 - qL)/2. Leader profit is qL(100 - qL)/2, whose maximum occurs at qL = 50.", why: ["25 is below the leader's optimum after accounting for the follower response.", "40 is the symmetric Cournot output, not the Stackelberg leader output.", "Correct. The leader commits to 50 and the follower responds with 25.", "At 100 the price and profit are zero."] },
  { type: "GAME THEORY", question: "A subgame-perfect equilibrium eliminates non-credible threats by requiring...", options: ["Only the initial action to be optimal", "Sequential rationality in every subgame", "All players to have dominant strategies", "Equal payoffs for all players"], answer: 1, explanation: "Subgame perfection requires strategies to form a Nash equilibrium in every subgame, so continuation actions must be optimal when reached.", why: ["Optimality only at the initial node permits non-credible continuation threats.", "Correct. Sequential rationality is the defining refinement.", "Dominant strategies are not required.", "Equilibrium payoffs need not be equal."] },
  { type: "GAME THEORY", question: "In a finitely repeated prisoners' dilemma with known final period and standard payoffs, backward induction predicts...", options: ["Cooperation in every period", "Defection in every period", "Cooperation until the final period only", "No Nash equilibrium"], answer: 1, explanation: "In the last period both players defect. Since the final period outcome is fixed, the same logic unravels backward through every earlier period.", why: ["The final period provides no future reward for cooperation.", "Correct. Defection is the stage-game dominant strategy and backward induction extends it.", "The unraveling applies to earlier periods too.", "A Nash equilibrium exists; the issue is which equilibrium is selected."] },
  { type: "GAME THEORY", question: "A mixed-strategy equilibrium in matching pennies requires each player to...", options: ["Choose the action with the highest pure payoff", "Randomize so the opponent is indifferent between their pure actions", "Use a dominant strategy", "Coordinate on the socially efficient action"], answer: 1, explanation: "A player chooses mixing probabilities that make the opponent indifferent; otherwise the opponent would prefer one pure action and would not mix.", why: ["There is no stable pure best response pair in matching pennies.", "Correct. Indifference supports randomization in equilibrium.", "Matching pennies has no dominant-strategy equilibrium.", "The game is deliberately conflicting rather than a coordination problem."] },
  { type: "AUCTIONS", question: "In a standard independent-private-values first-price sealed-bid auction, a risk-neutral bidder generally bids...", options: ["Above their valuation", "Exactly their valuation", "Below their valuation to retain an information rent", "Zero regardless of valuation"], answer: 2, explanation: "Bidding below value trades off a lower chance of winning against a positive surplus conditional on winning. Bidding above value risks a loss.", why: ["A bid above value can yield negative profit if the bidder wins.", "Truthful bidding is weakly dominant in a second-price auction, not generally in first-price auctions.", "Correct. Bid shading preserves expected surplus.", "A bidder with a high value generally submits a positive bid."] },
  { type: "GAME THEORY", question: "A credible entry-deterrence strategy must...", options: ["Threaten an action that would be irrational after entry", "Make the incumbent's continuation action optimal after entry", "Guarantee the entrant negative profits before entry", "Require a cartel agreement"], answer: 1, explanation: "A threat deters entry only if it is optimal for the incumbent to carry it out after entry. Otherwise the entrant will ignore it.", why: ["Non-credible threats are eliminated by backward induction.", "Correct. Credibility is sequential rationality after entry.", "The entrant's expected profit depends on the credible response, not a pre-entry guarantee.", "Cartel formation is not required for an entry threat."] },
  // Labor, capital, and intertemporal choice
  { type: "FACTOR MARKETS", question: "A profit-maximizing competitive firm hires labor until...", options: ["Wage equals the average product of labor", "Wage equals the value of the marginal product of labor", "Wage equals total revenue", "Marginal product equals zero"], answer: 1, explanation: "The firm hires labor while the extra revenue from another worker exceeds the wage. The condition is VMP_L = P x MPL = w.", why: ["Average product does not determine the marginal hiring decision.", "Correct. The firm hires until the value of marginal product equals the wage.", "Total revenue is not a per-worker marginal comparison.", "Hiring may stop before marginal product reaches zero."] },
  { type: "CALCULATION", question: "A competitive firm sells output at P = 10. The marginal product of the next worker is 5 units, and the wage is 55. Should the firm hire that worker?", options: ["Yes, because MPL exceeds wage", "Yes, because revenue is 50", "No, because VMP = 50 < wage = 55", "No, because marginal product must be zero"], answer: 2, explanation: "The worker adds value P x MPL = 10 x 5 = 50, less than the 55 wage. Hiring would reduce profit.", why: ["MPL and wage have different units and cannot be compared directly.", "Revenue of 50 is below the wage, so it does not support hiring.", "Correct. The value of marginal product is 50, below the wage.", "A positive marginal product can still be unprofitable if its value is below wage."] },
  { type: "FACTOR MARKETS", question: "A monopsonist's marginal expenditure on labor lies above its labor supply curve because...", options: ["The firm is a price taker in labor", "To hire another worker, it must raise the wage paid to existing workers", "Workers have no reservation wage", "Labor supply is perfectly elastic"], answer: 1, explanation: "With an upward-sloping labor supply, attracting an additional worker requires a higher wage, and that higher wage applies to previous workers too.", why: ["A monopsonist is the opposite of a labor-market price taker.", "Correct. The inframarginal wage increase makes marginal expenditure exceed wage.", "Reservation wages help generate the supply curve.", "Perfectly elastic supply would make marginal expenditure equal the wage."] },
  { type: "FACTOR MARKETS", question: "A binding minimum wage in a monopsonistic labor market can...", options: ["Only reduce employment", "Raise both the wage and employment over some range", "Never affect the monopsonist", "Eliminate the labor supply curve"], answer: 1, explanation: "A moderate wage floor can remove the monopsonist's wage-setting margin, making the relevant labor supply effectively flatter and increasing employment.", why: ["Unlike perfect competition, a moderate floor can correct monopsony underemployment.", "Correct. It can raise employment until the floor exceeds the competitive-range wage.", "A binding floor necessarily changes the firm's cost of labor.", "The underlying worker supply relationship remains."] },
  { type: "INTERTEMPORAL CHOICE", question: "For an interior two-period consumption optimum, the Euler condition is...", options: ["MU(C1) = MU(C2) always", "MU(C1) = (1+r)MU(C2) in the simplest undiscounted case", "C1 = C2 regardless of interest", "The consumer spends all income in period 1"], answer: 1, explanation: "Giving up one unit today yields 1+r units tomorrow. At the optimum, the marginal utility cost today equals the discounted marginal utility benefit tomorrow.", why: ["Marginal utilities differ when the interest rate or discounting differs.", "Correct for beta = 1: MU1 = (1+r)MU2.", "Consumption equality is not implied by optimality.", "Interior solutions allocate consumption across periods rather than exhausting period 1 income."] },
  { type: "CAPITAL", question: "The user cost of capital rises when...", options: ["The interest rate and depreciation rate both fall", "The interest rate or depreciation rate rises, holding the asset price fixed", "The marginal product of capital rises", "The capital stock is fixed forever"], answer: 1, explanation: "A common user-cost expression is (r + delta)PK, so either a higher interest rate or higher depreciation raises the rental cost of capital.", why: ["Lower financing and depreciation costs reduce user cost.", "Correct. Both terms increase the cost of using a capital asset.", "A higher marginal product affects desired demand, not the unit user cost directly.", "A fixed stock does not define its rental cost."] },
  // Externalities, public goods, and common resources
  { type: "EXTERNALITIES", question: "With a negative production externality, the competitive market produces...", options: ["Less than the socially efficient quantity", "More than the socially efficient quantity because private MC understates social MC", "The efficient quantity automatically", "No output because external costs are infinite"], answer: 1, explanation: "Firms consider private marginal cost but ignore external marginal damage. Therefore private supply lies below social cost and market output is too high.", why: ["The unpriced harm causes overproduction, not underproduction.", "Correct. Social MC = private MC + marginal external damage.", "The market equilibrium ignores the external harm.", "External costs can be finite while output remains positive."] },
  { type: "CALCULATION", question: "Private MC is 10 + Q and marginal external damage is Q. Demand is P = 50 - Q. What is the efficient quantity?", options: ["10", "13.33", "20", "30"], answer: 1, explanation: "Social MC = 10 + 2Q. Set demand equal to social MC: 50 - Q = 10 + 2Q, so 40 = 3Q and Q = 13.33.", why: ["Q = 10 does not equate demand to social MC.", "Correct. 40/3 is approximately 13.33.", "Q = 20 is the private-market quantity only if private MC is used incorrectly? Substitution gives demand 30 and SMC 50.", "Q = 30 makes demand zero and exceeds the efficient solution."] },
  { type: "EXTERNALITIES", question: "A Pigouvian tax implements the competitive social optimum when the tax equals...", options: ["Average external damage at zero output", "Marginal external damage at the efficient quantity", "The firm's fixed cost", "Consumer surplus"], answer: 1, explanation: "A per-unit tax equal to marginal external damage at the efficient output makes private marginal cost equal social marginal cost at that output.", why: ["The tax must reflect marginal harm at the relevant quantity, not at zero.", "Correct. It internalizes the marginal external cost.", "Fixed cost is unrelated to the externality wedge.", "Consumer surplus is not the marginal damage measure."] },
  { type: "EXTERNALITIES", question: "The Coase theorem predicts an efficient outcome when property rights are well-defined and...", options: ["Transaction costs are negligible", "The government sets all prices", "Income is equal", "External damage is zero by definition"], answer: 0, explanation: "With clear rights and negligible bargaining costs, affected parties can bargain to the efficient allocation regardless of the initial assignment of rights, though distribution changes.", why: ["Correct. Low transaction costs allow mutually beneficial bargaining.", "Government price setting is not required by the theorem.", "Equal income is not an assumption.", "The theorem addresses nonzero externalities."] },
  { type: "ENVIRONMENTAL ECONOMICS", question: "A cap-and-trade system reaches least-cost pollution abatement when firms...", options: ["Face identical abatement costs", "Equalize marginal abatement costs across firms", "All abate the same physical amount", "Receive no permits"], answer: 1, explanation: "The total cap determines aggregate emissions. Trading reallocates abatement until marginal abatement costs are equal, minimizing total compliance cost.", why: ["Identical costs are not necessary; trading is valuable precisely because costs differ.", "Correct. Equal MAC is the cost-minimizing allocation.", "Equal physical abatement can be expensive if firms have different technologies.", "Permits are the mechanism that creates flexibility; none is not required."] },
  { type: "PUBLIC GOODS", question: "The Samuelson condition for efficient provision of a pure public good is...", options: ["Each person's MRS equals the price separately", "The sum of individuals' MRS equals the marginal cost", "The public good is provided until one person's utility is zero", "Private marginal benefit equals private marginal cost for one consumer"], answer: 1, explanation: "Because all consumers can simultaneously enjoy another unit, marginal benefits are summed vertically: sum MRS = MC.", why: ["That is the private-good condition, not the public-good condition.", "Correct. Add individual marginal willingness to pay and equate it to MC.", "Efficiency does not require eliminating anyone's utility.", "One individual's benefit omits benefits to others."] },
  { type: "PUBLIC GOODS", question: "The free-rider problem occurs because a non-excludable public good...", options: ["Can be consumed by one person only", "Allows people to benefit without revealing willingness to pay", "Has a marginal cost that is always zero", "Is always rival in consumption"], answer: 1, explanation: "When exclusion is difficult, individuals can enjoy the good without paying, creating incentives to understate demand and causing underprovision.", why: ["Non-rival goods can be enjoyed jointly.", "Correct. The benefit can be received without contributing to finance.", "Production may have positive marginal cost.", "Pure public goods are non-rival, not rival."] },
  { type: "COMMON RESOURCES", question: "A common-pool resource is characterized by...", options: ["Excludability and non-rivalry", "Non-excludability and rivalry", "Excludability and rivalry", "Non-excludability and non-rivalry"], answer: 1, explanation: "Common resources are difficult to exclude users from, but one person's use reduces availability for others, leading to possible overuse.", why: ["That describes a club good.", "Correct. Fisheries and open-access forests are standard examples.", "That describes a private good.", "That describes a pure public good."] },
  // Information and contracts
  { type: "INFORMATION ECONOMICS", question: "Adverse selection is an information problem that occurs...", options: ["After a contract because effort is hidden", "Before a contract because types or quality are hidden", "Only when prices are regulated", "When all agents have identical information"], answer: 1, explanation: "Adverse selection is ex ante hidden information: the informed side's type affects participation, so the market's pool can become disproportionately low quality.", why: ["Hidden effort after contracting is moral hazard.", "Correct. It is a pre-contract sorting problem.", "It can occur without price regulation.", "Identical information removes the relevant asymmetry."] },
  { type: "INFORMATION ECONOMICS", question: "Moral hazard is most directly reduced by...", options: ["Ignoring effort after the contract", "Monitoring, deductibles, or incentive-compatible compensation", "Banning all insurance", "Making types observable before contracting only"], answer: 1, explanation: "Moral hazard arises from hidden action after contracting. Monitoring and risk-sharing contracts with incentives make effort more observable or consequential.", why: ["Ignoring hidden action leaves the problem unchanged.", "Correct. These tools align private incentives with desired behavior.", "Insurance can be designed to reduce rather than create moral hazard.", "Observing types addresses adverse selection, not hidden effort."] },
  { type: "SIGNALING", question: "In a separating signaling equilibrium, education can be socially wasteful when...", options: ["It increases productivity for every worker", "It is costly for low-productivity types but mainly redistributes beliefs about type", "Employers observe productivity perfectly", "Education has no cost to any type"], answer: 1, explanation: "A signal can separate types without raising output; resources are spent to alter beliefs and wages, creating a potential signaling externality or waste.", why: ["Productivity-enhancing education creates a real social benefit.", "Correct. Costly signaling can burn resources while reallocating income.", "Perfect observability eliminates the need for signaling.", "A costless signal creates no resource waste, though it may still convey information."] },
  { type: "SCREENING", question: "A menu of insurance contracts with different deductibles is an example of...", options: ["Screening by the uninformed party", "Signaling by the insurer's customers only", "A public good", "A price ceiling"], answer: 0, explanation: "The insurer designs a menu so customers self-select: high-risk customers prefer generous coverage while low-risk customers accept a higher deductible for a lower premium.", why: ["Correct. The uninformed insurer induces informed types to reveal themselves through choice.", "Customers select from the menu, but the design is screening by the insurer.", "Insurance contracts are private and excludable.", "A deductible is not a price ceiling."] },
  { type: "PRINCIPAL-AGENT", question: "An incentive contract is efficient when it balances...", options: ["Only the principal's payoff", "Risk sharing for the agent with incentives for hidden effort", "Zero compensation and perfect monitoring", "Equal payoffs regardless of performance"], answer: 1, explanation: "The principal wants effort, while a risk-averse agent values insurance. The optimal contract trades off incentives against risk-bearing and monitoring costs.", why: ["Ignoring the agent's participation and risk makes the contract infeasible or costly.", "Correct. This is the central principal-agent tradeoff.", "Perfect monitoring is generally unavailable or expensive.", "Equal pay regardless of performance weakens effort incentives."] },
  { type: "INFORMATION ECONOMICS", question: "A separating equilibrium differs from a pooling equilibrium because...", options: ["All types choose the same action in a separating equilibrium", "Different types choose different actions in a separating equilibrium", "No equilibrium exists in a pooling model", "Prices are always equal across types"], answer: 1, explanation: "In a separating equilibrium, actions or contracts reveal type because different types choose different options. In pooling, all types choose the same action.", why: ["Choosing the same action defines pooling.", "Correct. Observable behavior distinguishes types.", "Pooling and separating equilibria can both exist depending on beliefs and payoffs.", "Prices may differ or be equal depending on the model."] },
  // General equilibrium and welfare
  { type: "GENERAL EQUILIBRIUM", question: "The first welfare theorem states that under standard assumptions, a competitive equilibrium is...", options: ["Always equitable", "Pareto efficient", "Always unique", "Maximizes each firm's revenue"], answer: 1, explanation: "With complete markets, price-taking, no externalities, and other assumptions, competitive equilibrium is Pareto efficient, though it need not be equitable.", why: ["Efficiency does not imply a fair distribution.", "Correct. No one can be made better off without making someone else worse off.", "Multiple equilibria can exist.", "Firms maximize profit, not necessarily revenue."] },
  { type: "GENERAL EQUILIBRIUM", question: "The second welfare theorem supports separating efficiency from distribution because...", options: ["Any Pareto-efficient allocation can be decentralized after suitable lump-sum transfers under convexity", "Markets never need redistribution", "Taxes always improve efficiency", "Only monopolies can reach the contract curve"], answer: 0, explanation: "Under convex preferences and technologies, a planner can use lump-sum transfers to select a desired efficient allocation and then let competitive prices decentralize it.", why: ["Correct. It provides the conceptual case for redistribution first and efficiency through markets afterward.", "The theorem explicitly allows redistribution.", "Distortionary taxes can reduce efficiency; lump-sum transfers are special.", "The contract curve can be reached by competitive exchange, not only monopoly."] },
  { type: "GENERAL EQUILIBRIUM", question: "In an Edgeworth box, the contract curve contains allocations where...", options: ["One consumer has zero consumption", "The consumers' indifference curves are tangent, so MRS_A = MRS_B", "Prices are necessarily equal to one", "Total resources are expanding"], answer: 1, explanation: "Mutually beneficial trades are exhausted where the two consumers have equal marginal rates of substitution, subject to feasibility.", why: ["Boundary allocations can be on the contract curve but are not its defining condition.", "Correct. Tangency means no further mutually beneficial reallocation exists locally.", "Prices are not fixed by the box alone.", "The box represents fixed aggregate resources."] },
  { type: "GENERAL EQUILIBRIUM", question: "Walras' law implies that if all but one market clear, then...", options: ["The remaining market must also clear, given budget balance", "The remaining market must have excess demand", "No equilibrium can exist", "Prices must all be zero"], answer: 0, explanation: "The value of aggregate excess demand is zero when agents satisfy their budget constraints. If all but one markets clear, the value of the final excess demand must also be zero.", why: ["Correct. The final market-clearing condition follows from the value identity.", "It cannot have nonzero valued excess demand if all other markets clear.", "Walras' law supports, rather than rules out, equilibrium accounting.", "Positive prices are compatible with the law."] },
  { type: "WELFARE", question: "A Kaldor-Hicks improvement occurs when...", options: ["Everyone is made better off with no compensation", "Gainers could hypothetically compensate losers and still remain better off", "Only the poorest person gains", "Total output falls but inequality rises"], answer: 1, explanation: "Kaldor-Hicks efficiency uses potential compensation: the winners' gains are large enough to compensate losers, whether or not transfer actually occurs.", why: ["That is a Pareto improvement, which is stronger.", "Correct. It is based on net potential gains rather than actual compensation.", "The identity of gainers is not the criterion.", "Higher inequality or lower output does not establish a potential-compensation gain."] },
  { type: "PUBLIC CHOICE", question: "The median voter theorem applies most directly when...", options: ["Preferences are single-peaked and voting is majority rule on a one-dimensional policy", "Voters have random multidimensional preferences", "There is no voting", "All voters have identical incomes"], answer: 0, explanation: "With single-peaked preferences on one policy dimension, the policy preferred by the median voter defeats alternatives in pairwise majority voting.", why: ["Correct. These are the key structure assumptions.", "Multidimensional preferences can generate cycling and do not support the simple theorem.", "Voting is essential to the result.", "Income equality is not required."] },
  { type: "PUBLIC CHOICE", question: "Arrow's impossibility theorem shows that no ranked-choice social welfare rule can satisfy all listed conditions when...", options: ["There are at least three alternatives and unrestricted individual preferences", "There are only two alternatives", "All preferences are identical", "There is a competitive market"], answer: 0, explanation: "Arrow's theorem concerns aggregating individual rankings over at least three alternatives while satisfying unrestricted domain, Pareto, non-dictatorship, and independence of irrelevant alternatives.", why: ["Correct. Three or more alternatives and unrestricted preferences are central.", "With two alternatives, several aggregation rules avoid the theorem.", "Identical preferences make aggregation straightforward.", "Competitive markets are not the theorem's domain."] },
  // International trade and applied micro
  { type: "INTERNATIONAL TRADE", question: "A country has comparative advantage in a good when it can produce it at...", options: ["The lowest absolute cost only", "The lowest opportunity cost relative to another country", "The highest wage", "The highest domestic price before trade"], answer: 1, explanation: "Comparative advantage depends on relative opportunity cost. A country can have absolute advantage in both goods but comparative advantage in only one.", why: ["Absolute advantage is a productivity comparison, not comparative advantage.", "Correct. Relative opportunity cost determines specialization gains.", "Wages alone do not identify opportunity cost.", "Pre-trade price reflects scarcity and demand as well as production technology."] },
  { type: "CALCULATION", question: "Country A gives up 2 wheat for 1 cloth; Country B gives up 4 wheat for 1 cloth. Which trade direction can benefit both?", options: ["A exports cloth and imports wheat", "B exports cloth and imports wheat", "Neither because A has lower opportunity cost in both goods", "Both export cloth simultaneously without imports"], answer: 0, explanation: "A has the lower opportunity cost of cloth (2 versus 4), so A should export cloth. B has comparative advantage in wheat and exports wheat.", why: ["Correct. Specialization follows lower opportunity cost.", "B has the higher opportunity cost of cloth and comparative advantage in wheat.", "The stated costs imply comparative advantages in opposite goods.", "Mutually beneficial trade requires each country to import the good with lower domestic opportunity cost."] },
  { type: "INTERNATIONAL TRADE", question: "For a small importing country, an import tariff generally...", options: ["Raises domestic price, reduces imports, and creates deadweight loss", "Lowers domestic price and increases imports", "Benefits consumers more than producers", "Has no effect if the country is small"], answer: 0, explanation: "A tariff wedges domestic price above the world price, reducing consumption and increasing domestic production while lowering imports. Production and consumption distortions create deadweight loss.", why: ["Correct. This is the standard small-country tariff result.", "The tariff raises rather than lowers the domestic price.", "Consumers lose from the higher price; protected producers gain.", "Small-country status means the country cannot change the world price, not that the tariff is irrelevant."] },
  { type: "INTERNATIONAL TRADE", question: "With a binding import quota, the quota rent accrues to...", options: ["Consumers automatically", "Those holding scarce import licenses or the government if licenses are auctioned", "Foreign producers in every case", "No one because quotas do not create rents"], answer: 1, explanation: "The quota creates a gap between the domestic and world price. The value of restricted import rights is a rent captured by license holders or by government auction revenue.", why: ["Consumers pay the higher price and generally lose surplus.", "Correct. The allocation mechanism determines who receives the rent.", "Foreign producers may gain from a higher export price, but quota rent is not automatically theirs.", "A binding quota creates scarcity rents by definition."] },
  { type: "INTERNATIONAL TRADE", question: "Compared with a tariff, an equivalent import quota is more likely to...", options: ["Generate automatic government revenue", "Allow quota rents to go to foreign exporters if they control licenses", "Leave domestic price unchanged", "Increase imports beyond the free-trade level"], answer: 1, explanation: "A tariff creates public revenue. A quota creates rents, but their distribution depends on who receives import rights; foreign exporters can capture them.", why: ["Quota rents are not automatically government revenue.", "Correct. License allocation and bargaining can transfer rents abroad.", "Both restrictions raise domestic price when binding.", "Both reduce imports relative to free trade."] },
  // Integrated calculations and advanced applications
  { type: "CALCULATION", question: "A monopolist has P = 80 - Q and total cost C = 20Q + 100. What output maximizes profit?", options: ["20", "30", "40", "60"], answer: 1, explanation: "TR = 80Q - Q^2, so MR = 80 - 2Q. MC = 20. Set MR = MC: 80 - 2Q = 20, yielding Q = 30.", why: ["At Q = 20, MR = 40 and the firm should expand.", "Correct. Q = 30 makes MR equal MC.", "At Q = 40, MR = 0, below MC.", "At Q = 60, price is 20 and marginal revenue is negative."] },
  { type: "CALCULATION", question: "A competitive industry's demand is P = 100 - Q and long-run supply is P = 20. A per-unit external damage of 10 exists. What is the efficient output?", options: ["70", "80", "90", "100"], answer: 0, explanation: "The social marginal cost is 20 + 10 = 30. Set demand equal to social MC: 100 - Q = 30, so Q = 70.", why: ["Correct. The external damage raises the relevant cost from 20 to 30.", "80 is the uncorrected competitive quantity when P = 20.", "90 does not satisfy 100 - Q = 30.", "At Q = 100, demand price is zero."] },
  { type: "CALCULATION", question: "A firm has production Q = 10L - L^2 and output price P = 6. If wage is 18, what labor choice satisfies P x MPL = w?", options: ["L = 1", "L = 2", "L = 3.5", "L = 5"], answer: 2, explanation: "MPL = 10 - 2L. Set 6(10 - 2L) = 18, so 60 - 12L = 18 and L = 3.5.", why: ["At L = 1, VMP = 48, above the wage.", "At L = 2, VMP = 36, still above the wage.", "Correct. At L = 3.5, MPL = 3 and VMP = 18.", "At L = 5, VMP = 0, below the wage."] },
  { type: "CALCULATION", question: "A consumer's budget is 4x + 2y = 40. If x = 6, what is the maximum affordable y?", options: ["4", "8", "16", "20"], answer: 1, explanation: "Substitute x = 6: 4(6) + 2y = 40, so 24 + 2y = 40 and y = 8.", why: ["4 is only half of the remaining budget after spending on x.", "Correct. y = (40 - 24)/2 = 8.", "16 is the remaining money, not the quantity of y.", "20 is the y-intercept when x = 0."] },
  { type: "CALCULATION", question: "A risk-neutral firm chooses insurance coverage when expected loss is 1,000 and the actuarially fair premium is 1,000. With full insurance, expected monetary wealth is...", options: ["Random with expected loss 1,000", "Certain wealth equal to initial wealth minus the premium", "Higher than initial wealth", "Zero in every state"], answer: 1, explanation: "At an actuarially fair premium, the premium equals expected loss. Full insurance removes the loss risk, leaving certain wealth equal to initial wealth less the premium.", why: ["Full insurance removes the random loss after the premium is paid.", "Correct. The premium is paid for certainty, so wealth is fixed.", "The fair premium does not create expected wealth.", "Initial wealth is not assumed to be zero."] },
  { type: "MARKET STRUCTURE", question: "A monopolistically competitive firm's long-run equilibrium typically has...", options: ["P = MC and minimum LRAC", "P > MC and zero economic profit, with excess capacity", "P < MC and positive economic profit", "A perfectly horizontal individual demand curve"], answer: 1, explanation: "Free entry removes economic profit, but product differentiation leaves downward-sloping demand, so P > MC. Tangency to LRAC occurs left of minimum LRAC, creating excess capacity.", why: ["P = MC and minimum LRAC describe long-run perfect competition.", "Correct. Entry eliminates profit without eliminating product market power.", "Profit is zero in the long run and P generally exceeds MC.", "A differentiated firm's demand is downward sloping, not horizontal."] },
  { type: "MARKET STRUCTURE", question: "A firm with a kinked demand curve model predicts price rigidity because...", options: ["Both demand segments are perfectly elastic", "A price cut is matched by rivals while a price increase is not", "Marginal cost never changes", "The firm is a price taker"], answer: 1, explanation: "Below the current price, rivals match a price cut so demand is relatively inelastic; above it, a price increase loses many customers. The resulting MR discontinuity can make price stable.", why: ["The two segments have different elasticities, not both perfect elasticity.", "Correct. Asymmetric rival responses create the kink.", "MC can move within the discontinuity without changing price.", "A kinked-demand firm has market power."] },
  { type: "WELFARE", question: "A subsidy for a positive consumption externality should be set, at the efficient quantity, equal to...", options: ["Marginal external benefit", "Average private benefit", "Marginal private cost", "Total consumer surplus"], answer: 0, explanation: "A subsidy equal to marginal external benefit makes consumers face the full social marginal benefit, aligning private choice with the social optimum.", why: ["Correct. It closes the gap between social and private marginal benefit.", "Average benefit is not the relevant marginal decision term.", "Private cost is not the unpriced benefit wedge.", "Total surplus is not a per-unit marginal incentive."] },
  { type: "INFORMATION ECONOMICS", question: "If insurers cannot distinguish high- and low-risk customers and must charge one pooled premium, adverse selection can cause...", options: ["Only low-risk customers to buy more coverage", "High-risk customers to be overrepresented, raising the pooled premium and potentially unraveling the market", "Perfect risk sharing at no cost", "Moral hazard to disappear"], answer: 1, explanation: "A pooled premium based on average risk may be unattractive to low-risk customers. Their exit raises average risk and premiums, potentially causing a market unraveling.", why: ["Low-risk customers may exit rather than buy more at an actuarially unfair pooled premium.", "Correct. This is the adverse-selection death spiral.", "Pooling is not costless when types differ and information is asymmetric.", "Adverse selection and moral hazard are distinct problems."] },
  { type: "GENERAL EQUILIBRIUM", question: "If an allocation is Pareto efficient, it is...", options: ["The only allocation that maximizes total utility", "Impossible to make someone better off without making someone else worse off", "Always equal in consumption", "Always attainable through a competitive equilibrium without transfers"], answer: 1, explanation: "Pareto efficiency is a no-waste criterion: no feasible reallocation can help someone without harming someone else. Many unequal allocations can be Pareto efficient.", why: ["There can be many Pareto-efficient allocations and no unique utilitarian objective.", "Correct. This is the definition.", "Efficiency does not imply equality.", "The second welfare theorem requires conditions and possibly transfers for decentralization."] },
  { type: "LABOR ECONOMICS", question: "If a worker's wage rises, the labor-leisure choice has a substitution effect that...", options: ["Makes leisure more expensive and tends to increase labor supplied", "Makes leisure cheaper and always reduces labor supplied", "Has no effect because leisure is not a good", "Raises nonlabor income"], answer: 0, explanation: "A higher wage raises the opportunity cost of an hour of leisure, encouraging substitution toward work. The income effect may offset this, so total labor response is ambiguous.", why: ["Correct. Leisure costs more forgone earnings when the wage rises.", "The substitution effect points toward work, though the income effect may point toward leisure.", "Leisure is a normal economic good in the model.", "A wage change is not automatically a transfer of nonlabor income."] },
  { type: "ENVIRONMENTAL ECONOMICS", question: "When marginal abatement costs are equalized across firms, a further small reallocation of abatement...", options: ["Must lower total cost", "Cannot lower total cost to first order", "Always raises emissions", "Changes the emissions cap"], answer: 1, explanation: "If one firm has the same marginal cost as another, moving a small unit of abatement between them does not reduce total cost to first order. This is the least-cost condition.", why: ["There is no first-order cost saving when marginal costs are already equal.", "Correct. Equal MAC is the cost-minimizing allocation for the fixed cap.", "Reallocation need not change total emissions.", "The cap is fixed; only who abates changes."] },
  { type: "CALCULATION", question: "A firm's inverse demand is P = 50 - Q and MC = 10. At Q = 15, what is the marginal revenue?", options: ["5", "20", "35", "50"], answer: 1, explanation: "For P = a - bQ, MR = a - 2bQ = 50 - 2(15) = 20.", why: ["5 is not obtained from the marginal-revenue formula.", "Correct. MR = 20.", "35 is the price at Q = 15, not marginal revenue.", "50 is the demand intercept at zero output."] },
  { type: "CONSUMER THEORY", question: "For a quasi-linear utility function U = x + v(y), the income effect on demand for x is often zero because...", options: ["x is inferior", "The marginal utility of x is constant and income changes are absorbed by x after the nonlinear good is chosen", "Prices do not matter", "The consumer has no budget constraint"], answer: 1, explanation: "With quasi-linear utility and an interior solution, changes in income change the quantity of the linear numeraire x while leaving demand for y unchanged; x's marginal utility is constant.", why: ["Quasi-linearity does not make x necessarily inferior.", "Correct. The nonlinear good's demand is independent of income in the interior region.", "Prices still determine the optimum.", "The budget constraint remains essential."] }
];

// The live exam uses the first 70 advanced items plus the original 30 PPC items.
questions.push(...advancedQuestions.slice(0, 70));

const $ = (id) => document.getElementById(id);
const introPanel = $("intro-panel");
const quizPanel = $("quiz-panel");
const resultsPanel = $("results-panel");

function renderQuestion() {
  const item = questions[currentQuestion];
  $("question-count").textContent = `Question ${currentQuestion + 1} of ${questions.length}`;
  $("progress-percent").textContent = `${Math.round(((currentQuestion + 1) / questions.length) * 100)}% complete`;
  $("progress-bar").style.width = `${((currentQuestion + 1) / questions.length) * 100}%`;
  $("question-type").textContent = item.type;
  $("question-title").textContent = item.question;
  $("question-number").textContent = String(currentQuestion + 1).padStart(2, "0");
  $("prev-btn").disabled = currentQuestion === 0;
  $("next-btn").innerHTML = currentQuestion === questions.length - 1 ? "Finish quiz <span>✓</span>" : "Next question <span>→</span>";

  const visual = $("visual-container");
  if (item.visual) {
    visual.innerHTML = item.visual;
    visual.classList.remove("hidden");
  } else {
    visual.innerHTML = "";
    visual.classList.add("hidden");
  }

  $("options").innerHTML = item.options.map((option, index) => `
    <button class="option ${answers[currentQuestion] === index ? "selected" : ""}" data-index="${index}" role="radio" aria-checked="${answers[currentQuestion] === index}">
      <span class="option-letter">${String.fromCharCode(65 + index)}</span>
      <span class="option-text">${option}</span>
    </button>
  `).join("");

  document.querySelectorAll(".option").forEach((button) => {
    button.addEventListener("click", () => {
      answers[currentQuestion] = Number(button.dataset.index);
      renderQuestion();
    });
  });
  renderQuestionGrid();
}

function renderQuestionGrid() {
  $("question-grid").innerHTML = questions.map((_, index) => `
    <button class="${index === currentQuestion ? "current" : ""} ${answers[index] !== null ? "answered" : ""}" aria-label="Go to question ${index + 1}">${index + 1}</button>
  `).join("");
  document.querySelectorAll("#question-grid button").forEach((button, index) => {
    button.addEventListener("click", () => {
      currentQuestion = index;
      renderQuestion();
    });
  });
  $("answered-count").textContent = `${answers.filter((answer) => answer !== null).length}/${questions.length}`;
}

function updateTimer() {
  const minutes = Math.floor(secondsLeft / 60).toString().padStart(2, "0");
  const seconds = (secondsLeft % 60).toString().padStart(2, "0");
  $("timer").textContent = `${minutes}:${seconds}`;
  $("timer").classList.toggle("warning", secondsLeft <= 300 && secondsLeft > 60);
  $("timer").classList.toggle("danger", secondsLeft <= 60);
  if (secondsLeft <= 0) finishQuiz(true);
  secondsLeft -= 1;
}

function startTimer() {
  startedAt = Date.now();
  updateTimer();
  timerId = setInterval(updateTimer, 1000);
}

function finishQuiz(timeExpired = false) {
  if (timerId) clearInterval(timerId);
  timerId = null;
  const correct = answers.reduce((total, answer, index) => total + (answer === questions[index].answer ? 1 : 0), 0);
  const incorrect = questions.length - correct;
  const usedSeconds = quizDuration - Math.max(secondsLeft, 0);
  const usedMinutes = Math.floor(usedSeconds / 60).toString().padStart(2, "0");
  const usedRemainder = (usedSeconds % 60).toString().padStart(2, "0");
  $("score-value").textContent = `${Math.round((correct / questions.length) * 100)}%`;
  $("correct-stat").textContent = correct;
  $("incorrect-stat").textContent = incorrect;
  $("time-stat").textContent = `${usedMinutes}:${usedRemainder}`;
  $("results-title").textContent = timeExpired ? "Time is up." : correct >= 80 ? "Excellent work." : correct >= 60 ? "Good progress." : "Keep practicing.";
  $("results-summary").textContent = `You answered ${correct} out of ${questions.length} questions correctly. Review the explanations below to strengthen your microeconomics reasoning.`;
  const missed = questions.map((item, index) => ({ item, index })).filter(({ item, index }) => answers[index] !== item.answer);
  $("review-section").innerHTML = missed.length ? `
    <h3>Review missed questions</h3>
    ${missed.map(({ item, index }) => `
      <article class="review-card">
        <h3>${index + 1}. ${item.question}</h3>
        <p><strong>Your answer:</strong> ${answers[index] === null ? "Not answered" : `${String.fromCharCode(65 + answers[index])}. ${item.options[answers[index]]}`}</p>
        <p class="correct-answer"><strong>Correct answer:</strong> ${String.fromCharCode(65 + item.answer)}. ${item.options[item.answer]}</p>
        <p><strong>Why:</strong> ${item.explanation}</p>
        <div class="option-explanations">
          ${item.options.map((option, optionIndex) => `<p><strong>${String.fromCharCode(65 + optionIndex)}.</strong> ${item.why[optionIndex]}</p>`).join("")}
        </div>
      </article>
    `).join("")}
  ` : "<h3>Perfect score - no answers to review.</h3>";
  quizPanel.classList.add("hidden");
  resultsPanel.classList.remove("hidden");
  window.scrollTo({ top: 0, behavior: "smooth" });
}

$("start-btn").addEventListener("click", () => {
  introPanel.classList.add("hidden");
  quizPanel.classList.remove("hidden");
  answers = Array(questions.length).fill(null);
  startTimer();
  renderQuestion();
});
$("prev-btn").addEventListener("click", () => {
  if (currentQuestion > 0) {
    currentQuestion -= 1;
    renderQuestion();
  }
});
$("next-btn").addEventListener("click", () => {
  if (currentQuestion < questions.length - 1) {
    currentQuestion += 1;
    renderQuestion();
  } else {
    finishQuiz();
  }
});
$("restart-btn").addEventListener("click", () => {
  answers = Array(questions.length).fill(null);
  currentQuestion = 0;
  secondsLeft = quizDuration;
  resultsPanel.classList.add("hidden");
  introPanel.classList.remove("hidden");
  $("timer").textContent = "60:00";
  $("timer").className = "timer";
});
